// SetDeclaredByUser of the incident to the related item.
// Sets o.R.DeclaredByUser to related.
// Adds o to related.R.DeclaredByIncidents.
func (o *Incident) SetDeclaredByUser(ctx context.Context, exec boil.ContextExecutor, insert bool, related *User) error {
	var err error
	if insert {
		if err = related.Insert(ctx, exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE \"incidents\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, []string{"declared_by"}),
		strmangle.WhereClause("\"", "\"", 2, incidentPrimaryKeyColumns),
	)
	values := []any{related.ID, o.ID}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, updateQuery)
		fmt.Fprintln(writer, values)
	}
	if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	queries.Assign(&o.DeclaredBy, related.ID)
	if o.R == nil {
		o.R = &incidentR{
			DeclaredByUser: related,
		}
	} else {
		o.R.DeclaredByUser = related
	}

	if related.R == nil {
		related.R = &userR{
			DeclaredByIncidents: IncidentSlice{o},
		}
	} else {
		related.R.DeclaredByIncidents = append(related.R.DeclaredByIncidents, o)
	}

	return nil
}

// RemoveDeclaredByUser relationship.
// Sets o.R.DeclaredByUser to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Incident) RemoveDeclaredByUser(ctx context.Context, exec boil.ContextExecutor, related *User) error {
	var err error

	queries.SetScanner(&o.DeclaredBy, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("declared_by")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.DeclaredByUser = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.DeclaredByIncidents {
		if queries.Equal(o.DeclaredBy, ri.DeclaredBy) {
			continue
		}

		ln := len(related.R.DeclaredByIncidents)
		if ln > 1 && i < ln-1 {
			related.R.DeclaredByIncidents[i] = related.R.DeclaredByIncidents[ln-1]
		}
		related.R.DeclaredByIncidents = related.R.DeclaredByIncidents[:ln-1]
		break
	}
	return nil
}

